fn largest_divisor(n: i8) -> i8 {
    // Since n > 1, the largest proper divisor will never exceed n/2.
    // We scan downward from n/2 to 2, returning the first divisor we find.
    // If none > 1 is found, the number is prime and we return 1.
    for d in (2..=n / 2).rev() {
        if n % d == 0 {
            return d;
        }
    }
    1
}

